import itertools

def all_clauses(vars_):
    # vars_ list of variable names; clause = tuple of (var, sign) with 3 distinct vars
    res = []
    for combo in itertools.combinations(vars_, 3):
        for signs in itertools.product([1,-1], repeat=3):
            res.append(tuple(zip(combo, signs)))
    return res

def sat_clause(clause, assign):
    # exactly one literal true
    cnt = 0
    for v,s in clause:
        val = assign[v]
        if s == -1:
            val = not val
        if val:
            cnt += 1
    return cnt == 1

def formula_sat(formula, assign):
    return all(sat_clause(c, assign) for c in formula)

def projection_ok(formula, inputs, auxvars):
    # inputs: list of tuples for A,B,C
    # for each input, check exists aux assignment
    for inp in inputs:
        found = False
        for auxvals in itertools.product([False,True], repeat=len(auxvars)):
            assign = {}
            for name,val in zip(['A','B','C'], inp):
                assign[name]=val
            for name,val in zip(auxvars, auxvals):
                assign[name]=val
            if formula_sat(formula, assign):
                found = True
                break
        if not found:
            return False
    return True

# Try k aux variables, search clause sets up to size maxc
