    print("k=",k,"num clauses",len(cl))
    inputs_nonzero = [t for t in itertools.product([False,True],repeat=3) if any(t)]
    zero = (False,False,False)
    found_any = False
    for size in range(1,5):
        for combo in itertools.combinations(range(len(cl)), size):
            formula = [cl[i] for i in combo]
            # check zero unsat
            ok_zero = True
            for auxvals in itertools.product([False,True], repeat=k):
                assign = {'A':False,'B':False,'C':False}
                for name,val in zip(auxvars, auxvals):
                    assign[name]=val
                if formula_sat(formula, assign):
                    ok_zero=False; break
            if not ok_zero:
                continue
            if projection_ok(formula, inputs_nonzero, auxvars):
                print("FOUND size",size)
                for c in formula:
                    print("   ", c)
                found_any=True
                break
        if found_any:
            break
    if not found_any:
        print("none up to size 4")
