{"command":"cd /tmp/reduction-wc7903cl && cat > search.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int K; // number of aux vars
int NV; // total vars = 3 + K
int NCL;
int *cl_vars; // [NCL][3]
int *cl_sign; // [NCL][3] 1 = positive, -1 = negative
// mask[clause][input] where input 0..7 corresponds to (A,B,C) bits
unsigned int mask[2000][8];

int main(int argc, char**argv){
    K = atoi(argv[1]);
    int maxsize = atoi(argv[2]);
    NV = 3 + K;
    // enumerate clauses: choose 3 distinct vars from NV, signs
    int cv[2000][3], cs[2000][3];
    NCL=0;
    for(int a=0;a<NV;a++)for(int b=a+1;b<NV;b++)for(int c=b+1;c<NV;c++){
        for(int s=0;s<8;s++){
            cv[NCL][0]=a;cv[NCL][1]=b;cv[NCL][2]=c;
            cs[NCL][0]=(s&1)?1:-1;
            cs[NCL][1]=(s&2)?1:-1;
            cs[NCL][2]=(s&4)?1:-1;
            NCL++;
        }
    }
    // compute masks
    for(int i=0;i<NCL;i++){
        for(int inp=0;inp<8;inp++){
            unsigned int m=0;
            for(int aux=0;aux<(1<<K);aux++){
                // assignment: A,B,C from inp bits, aux from aux bits
                int assign[16];
                assign[0]=(inp>>0)&1; assign[1]=(inp>>1)&1; assign[2]=(inp>>2)&1;
                for(int j=0;j<K;j++) assign[3+j]=(aux>>j)&1;
                int cnt=0;
                for(int t=0;t<3;t++){
                    int v=assign[cv[i][t]];
                    if(cs[i][t]==-1) v=1-v;
                    cnt+=v;
                }
                if(cnt==1) m|=(1u<<aux);
            }
            mask[i][inp]=m;
        }
    }
    // enumerate subsets of size up to maxsize
    int idx[16];
    for(int size=1; size<=maxsize; size++){
        // combinations
        for(int i=0;i<size;i++) idx[i]=i;
        long long count=0;
        while(1){
            count++;
            // check
            unsigned int acc[8];
            for(int inp=0;inp<8;inp++) acc[inp]=0xFFFFFFFFu;
            for(int i=0;i<size;i++){
                for(int inp=0;inp<8;inp++) acc[inp]&=mask[idx[i]][inp];
            }
            if(acc[0]==0){
                int ok=1;
                for(int inp=1;inp<8;inp++) if(acc[inp]==0){ok=0;break;}
                if(ok){
                    printf("FOUND K=%d size=%d\n",K,size);
                    for(int i=0;i<size;i++){
                        printf("  clause:");
                        for(int t=0;t<3;t++) printf(" %s%d", cs[idx[i]][t]==1?"+":"-", cv[idx[i]][t]);
                        printf("\n");
                    }
                    return 0;
                }
            }
            // next combination
            int pos=size-1;
            while(pos>=0 && idx[pos]==NCL-size+pos) pos--;
            if(pos<0) break;
            idx[pos]++;
            for(int j=pos+1;j<size;j++) idx[j]=idx[j-1]+1;
        }
        printf("size %d done, %lld candidates\n", size, count);
    }
    printf("none\n");
    return 0;
}
EOF
