#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int K, NV, NCL, maxsize;
int cv[5000][3], cs[5000][3];
unsigned long long mask[5000][8]; // for each clause, for each input 0..7, set of aux assignments
unsigned long long full;

int found=0;
int chosen[64];
int nchosen=0;

void dfs(int start, unsigned long long *acc){
    if(found) return;
    if(acc[0]==0){
        // success: all nonzero must be nonzero (guaranteed by pruning)
        found=1;
        printf("FOUND K=%d size=%d\n",K,nchosen);
        for(int i=0;i<nchosen;i++){
            int c=chosen[i];
            printf("  (");
            for(int t=0;t<3;t++) printf("%s%d%s", cs[c][t]==1?"+":"-", cv[c][t], t<2?",":"");
            printf(")\n");
        }
        return;
    }
    if(nchosen>=maxsize) return;
    for(int i=start;i<NCL;i++){
        unsigned long long na[8];
        int ok=1;
        for(int inp=0;inp<8;inp++){
            na[inp]=acc[inp]&mask[i][inp];
            if(inp!=0 && na[inp]==0){ok=0;break;}
        }
        if(!ok) continue;
        chosen[nchosen++]=i;
        dfs(i+1,na);
        nchosen--;
        if(found) return;
    }
}

int main(int argc,char**argv){
    K=atoi(argv[1]); maxsize=atoi(argv[2]);
    NV=3+K;
    full = (K>=6)? ~0ULL : ((1ULL<<(1<<K))-1);
    NCL=0;
    for(int a=0;a<NV;a++)for(int b=a+1;b<NV;b++)for(int c=b+1;c<NV;c++){
        for(int s=0;s<8;s++){
            cv[NCL][0]=a;cv[NCL][1]=b;cv[NCL][2]=c;
            cs[NCL][0]=(s&1)?1:-1;
            cs[NCL][1]=(s&2)?1:-1;
            cs[NCL][2]=(s&4)?1:-1;
            NCL++;
        }
    }
    for(int i=0;i<NCL;i++){
        for(int inp=0;inp<8;inp++){
            unsigned long long m=0;
            int total=1<<K;
            for(int aux=0;aux<total;aux++){
                int assign[16];
                assign[0]=(inp>>0)&1; assign[1]=(inp>>1)&1; assign[2]=(inp>>2)&1;
                for(int j=0;j<K;j++) assign[3+j]=(aux>>j)&1;
                int cnt=0;
                for(int t=0;t<3;t++){
                    int v=assign[cv[i][t]];
                    if(cs[i][t]==-1) v=1-v;
                    cnt+=v;
                }
                if(cnt==1) m|=(1ULL<<aux);
            }
            mask[i][inp]=m;
        }
    }
    unsigned long long acc[8];
    for(int i=0;i<8;i++) acc[i]=full;
    dfs(0,acc);
    if(!found) printf("none K=%d maxsize=%d\n",K,maxsize);
    return 0;
}
EOF
